#pragma once

#define ROBOT_FACE_THEME_GIF_CSS \
    R"THEME(.face-gif-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:9px;margin:14px 0}.face-gif-row{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:9px 10px;border:1px solid var(--line);border-radius:11px;background:#091626}.face-gif-row label{min-width:74px;color:#cfdaea;font-size:11px;font-weight:700}.face-gif-row input{max-width:calc(100% - 80px);min-width:0;color:var(--muted);font-size:10px}.face-gif-settings{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:10px}.face-gif-settings input[type=color]{height:38px;padding:4px}.face-gif-bulk{display:grid;gap:6px;padding:12px;border:1px solid var(--line);border-radius:12px;background:#091626}.face-gif-bulk small{color:var(--muted);font-size:11px;line-height:1.5}.face-gif-batch-list{display:grid;gap:6px;margin-top:8px}.face-gif-batch-item{display:grid;grid-template-columns:minmax(120px,1fr) auto minmax(155px,220px) auto auto;align-items:center;gap:8px;padding:7px 9px;border:1px solid var(--line);border-radius:8px;background:#0b1829}.face-gif-batch-item select{min-width:0;padding:6px 8px;font-size:11px}.face-gif-batch-item button.face-gif-batch-save{background:var(--accent);color:#071522}.face-gif-batch-item button.face-gif-batch-save:disabled{opacity:.45;cursor:default}.face-gif-batch-item.is-pending{border-color:#4d9cff}.face-gif-batch-item.is-duplicate{border-color:#ff5368;background:#301722}.face-gif-batch-item.is-unknown{border-color:#d1a04e;background:#2a2418}.face-gif-batch-name{min-width:0;overflow-wrap:anywhere;font-size:11px}.face-gif-batch-status{font-size:10px;color:var(--muted)}.face-gif-batch-item.is-duplicate .face-gif-batch-status{color:#ff8291}.face-gif-batch-item.is-unknown .face-gif-batch-status{color:#f3c76b}.face-gif-batch-item button{min-width:0!important;padding:5px 8px;background:#69283b;font-size:10px}@media(max-width:520px){.face-gif-batch-item{grid-template-columns:minmax(0,1fr) auto;gap:6px}.face-gif-batch-name{grid-column:1;grid-row:1}.face-gif-batch-status{grid-column:1;grid-row:2}.face-gif-batch-item select{grid-column:1;grid-row:3}.face-gif-batch-item button.face-gif-batch-save{grid-column:2;grid-row:3}.face-gif-batch-item button.face-gif-batch-remove{grid-column:2;grid-row:1/3}}.face-gif-progress{width:100%;height:12px;margin:8px 0;accent-color:var(--accent)}.face-gif-tools{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.face-gif-tools button{min-width:190px}.face-gif-delete{margin-top:8px;background:#69283b}.face-gif-note{margin:8px 0;color:var(--muted);font-size:11px;line-height:1.6}@media(max-width:520px){.face-gif-grid{grid-template-columns:1fr}.face-gif-tools button{width:100%}})THEME"

#define ROBOT_FACE_THEME_GIF_HTML \
    R"THEME(<article class="card wide"><div class="card-head"><div><h2>Tạo theme biểu cảm động</h2><p>Chọn tên theme và GIF cho các trạng thái. Trình duyệt tự thu nhỏ, giảm màu rồi tải trực tiếp lên microSD.</p></div><span class="tag">GIF · MICROSD</span></div><details class="advanced"><summary>Tạo theme GIF mới · tối đa 17 biểu cảm</summary><div class="advanced-body">)THEME" \
    R"THEME(<div class="face-gif-settings"><div class="field"><label for="faceGifName">Tên theme</label><input id="faceGifName" maxlength="64" placeholder="Ví dụ: Cherry mùa xuân"></div><div class="field"><label for="faceGifId">Mã theme</label><input id="faceGifId" maxlength="32" placeholder="cherry-mua-xuan"></div><div class="field"><label for="faceGifStyle">Kiểu dự phòng khi thiếu GIF</label><select id="faceGifStyle"><option value="rounded">Rounded</option><option value="soft">Soft</option><option value="pixel">Pixel</option><option value="holo">Holo</option><option value="orbital">Orbital</option><option value="plasma">Plasma</option><option value="demon">Demon</option><option value="capybara">Capybara</option><option value="shiba">Shiba</option><option value="mochi">Mochi</option></select></div><div class="field"><label for="faceGifBackground">Màu nền</label><input id="faceGifBackground" type="color" value="#000000"></div><div class="field"><label for="faceGifPrimary">Màu theme dự phòng</label><input id="faceGifPrimary" type="color" value="#0abde3"></div><div class="field"><label for="faceGifAccent">Màu nhấn</label><input id="faceGifAccent" type="color" value="#ff70ae"></div><div class="field"><label for="faceGifTear">Màu chi tiết</label><input id="faceGifTear" type="color" value="#69d9ff"></div></div>)THEME" \
    R"THEME(<p class="face-gif-note">Có thể chọn một hoặc nhiều trạng thái; trạng thái chưa có GIF sẽ dùng gương mặt vẽ sẵn. Mỗi GIF nguồn tối đa 10 MiB/512×512/120 khung; file sau chuẩn hóa tối đa 256 KiB, 160×160 và 10 fps. GIF được xử lý trên máy tính/điện thoại đang mở trang, không gửi lên máy chủ.</p><div class="face-gif-bulk"><label for="faceGifBatch">Chọn nhiều GIF cùng lúc</label><input id="faceGifBatch" type="file" accept="image/gif,.gif" multiple><small>Tên file cần khớp với biểu cảm, ví dụ Happy.gif, Angry.gif, Neutral.gif hoặc Vui.gif, Tức giận.gif, Bình thường.gif. Không phân biệt hoa/thường, dấu tiếng Việt, khoảng trắng hay dấu gạch nối. Sau khi cài, hệ thống tự đổi tên thành khóa chuẩn như happy.gif, angry.gif, neutral.gif. “Trùng” nghĩa là nhiều tên file cùng ánh xạ tới một biểu cảm (ví dụ Sad.gif và Buồn.gif), không phải tên file giống nhau. Mỗi dòng có danh sách biểu cảm và nút Ghi để đổi mapping, hoặc Bỏ file để loại file. Tên chưa nhận diện có thể gán bằng danh sách biểu cảm ngay trên dòng đó.</small><details><summary>Danh sách tên file được nhận diện</summary><small>Neutral (Idle, Bình thường) · Happy (Smile, Vui) · Sad (Cry, Buồn) · Angry (Tức giận) · Surprised (Shocked, Ngạc nhiên) · Sleepy (Buồn ngủ) · Confused (Thinking, Bối rối) · Listening (Đang nghe) · Laugh (Laughing, Cười) · Love (Loving, Đáng yêu) · Dizzy (Chóng mặt) · Distracted (Mất tập trung) · Devil (Mischievous, Tinh nghịch) · Confident (Cool, Tự tin) · Yawn (Ngáp) · Playful (Wink, Nháy mắt) · Speaking (Talking, Đang nói). Phần trong ngoặc là tên thay thế được hỗ trợ. Tên file thêm hậu tố như Happy-v2.gif không tự nhận diện; hãy chọn biểu cảm đúng trong danh sách của file rồi bấm Ghi.</small></details><div id="faceGifBatchList" class="face-gif-batch-list" aria-live="polite"></div></div>)THEME" \
    R"THEME(<div class="face-gif-tools"><button id="faceGifInstall" class="primary" onclick="installFaceGifTheme()">Chuẩn hóa và cài vào thẻ nhớ</button><span id="faceGifProgressText" class="hint">Chọn ít nhất một file GIF.</span></div><progress id="faceGifProgress" class="face-gif-progress" value="0" max="100"></progress></div></details><div id="faceGifCreatorStatus" class="statusline" role="status" aria-live="polite"></div></article>)THEME"

#define ROBOT_FACE_THEME_GIF_SCRIPT \
    R"THEME(const faceGifExpressionDefs=[['neutral','Bình thường'],['happy','Vui'],['sad','Buồn'],['angry','Tức giận'],['surprised','Ngạc nhiên'],['sleepy','Buồn ngủ'],['confused','Bối rối'],['listening','Đang nghe'],['laugh','Cười'],['love','Đáng yêu'],['dizzy','Chóng mặt'],['distracted','Mất tập trung'],['devil','Tinh nghịch'],['confident','Tự tin'],['yawn','Ngáp'],['playful','Nháy mắt'],['speaking','Đang nói']];let faceGifIdTouched=false,faceGifBusy=false,faceGifBatchFiles=[];)THEME" \
    R"THEME(function faceGifSlug(value){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[đĐ]/g,'d').toLowerCase().replace(/[^a-z0-9_-]+/g,'-').replace(/^-+|-+$/g,'').slice(0,32)})THEME" \
    R"THEME($('faceGifName').addEventListener('input',()=>{if(!faceGifIdTouched)$('faceGifId').value=faceGifSlug($('faceGifName').value)});$('faceGifId').addEventListener('input',()=>{faceGifIdTouched=true;$('faceGifId').value=faceGifSlug($('faceGifId').value)});$('faceGifBatch').addEventListener('change',event=>{faceGifBatchFiles=Array.from(event.target.files||[]).map(file=>{const expression=faceGifKeyFromFilename(file.name);return{file,expression,pendingExpression:expression}});renderFaceGifBatchFiles()});)THEME" \
    R"THEME(async function faceStorageApi(params,options={}){const address='/api/storage?'+new URLSearchParams(params);const response=await fetch(address,options);let data={};try{data=await response.json()}catch(_){}if(!response.ok){const error=new Error(data.error||'HTTP '+response.status);error.status=response.status;throw error}if(data.ok===false)throw Error(data.error||'Thao tác microSD thất bại.');return data})THEME" \
    R"THEME(async function faceEnsureDirectory(path){try{await faceStorageApi({op:'mkdir',path},{method:'POST'})}catch(error){if(error.status!==409)throw error}})THEME" \
    R"THEME(function faceGifWorker(file,background,onProgress){return new Promise((resolve,reject)=>{const worker=new Worker('/api/face_themes/normalizer.js');const id=Math.random().toString(36).slice(2);worker.onmessage=event=>{const data=event.data||{};if(data.id!==id)return;if(data.type==='progress'){onProgress(data.progress);return}worker.terminate();if(data.type==='done')resolve(data);else reject(Error(data.error||'Không chuẩn hóa được GIF.'))};worker.onerror=event=>{worker.terminate();reject(Error(event.message||'Lỗi khi xử lý GIF trong trình duyệt.'))};file.arrayBuffer().then(buffer=>worker.postMessage({id,buffer,background},[buffer])).catch(error=>{worker.terminate();reject(error)})})})THEME" \
    R"THEME(async function faceThemeUpload(path,blob,onProgress){const chunkSize=32768;let offset=0;do{const chunk=blob.slice(offset,offset+chunkSize);await faceStorageApi({op:'upload',path,offset:String(offset),total:String(blob.size)},{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:chunk});offset+=chunk.size;onProgress(offset,blob.size)}while(offset<blob.size)})THEME" \
    R"THEME(function faceGifExpressionLabel(key){const match=faceGifExpressionDefs.find(([expression])=>expression===key);return match?match[1]+' ('+key+')':key}function renderFaceGifBatchFiles(){const host=$('faceGifBatchList');if(!host)return;host.replaceChildren();const grouped=new Map();for(const item of faceGifBatchFiles){const key=item.expression;if(key)grouped.set(key,(grouped.get(key)||[]).concat(item))}faceGifBatchFiles.forEach((item,index)=>{if(item.pendingExpression===undefined)item.pendingExpression=item.expression;const key=item.expression,duplicates=key&&(grouped.get(key)||[]).length>1,row=document.createElement('div');row.className='face-gif-batch-item'+(duplicates?' is-duplicate':(!key?' is-unknown':''));const name=document.createElement('span');name.className='face-gif-batch-name';name.textContent=item.file.name;const result=document.createElement('span');result.className='face-gif-batch-status';result.textContent=!key?'Chưa gán biểu cảm':duplicates?'Cùng biểu cảm với: '+grouped.get(key).filter(other=>other!==item).map(other=>other.file.name).join(', ')+' → '+faceGifExpressionLabel(key):'Gán → '+faceGifExpressionLabel(key);const select=document.createElement('select');select.setAttribute('aria-label','Biểu cảm của file '+item.file.name);const blank=document.createElement('option');blank.value='';blank.textContent='Chọn biểu cảm';select.append(blank);for(const [expression,label] of faceGifExpressionDefs){const option=document.createElement('option');option.value=expression;option.textContent=label+' ('+expression+')';select.append(option)}select.value=item.pendingExpression||'';const save=document.createElement('button');save.type='button';save.className='face-gif-batch-save';save.textContent='Ghi';save.disabled=select.value===(item.expression||'');select.addEventListener('change',()=>{item.pendingExpression=select.value||null;save.disabled=(item.pendingExpression||'')===(item.expression||'');row.classList.toggle('is-pending',!save.disabled)});save.addEventListener('click',()=>{item.expression=item.pendingExpression||null;renderFaceGifBatchFiles()});const remove=document.createElement('button');remove.type='button';remove.className='face-gif-batch-remove';remove.textContent='Bỏ file';remove.setAttribute('aria-label','Bỏ file '+item.file.name);remove.addEventListener('click',()=>{faceGifBatchFiles.splice(index,1);try{const transfer=new DataTransfer();faceGifBatchFiles.forEach(selected=>transfer.items.add(selected.file));$('faceGifBatch').files=transfer.files}catch(_){}renderFaceGifBatchFiles()});row.append(name,result,select,save,remove);host.append(row)});const status=$('faceGifCreatorStatus');if(status){const duplicateGroups=Array.from(grouped.entries()).filter(([,items])=>items.length>1);const unmapped=faceGifBatchFiles.filter(item=>!item.expression);const pending=faceGifBatchFiles.filter(item=>item.pendingExpression!==item.expression);if(duplicateGroups.length){status.textContent='Nhiều file cùng gán một biểu cảm: '+duplicateGroups.map(([key,items])=>faceGifExpressionLabel(key)+' ← '+items.map(item=>item.file.name).join(', ')).join('; ')+'. Đổi mapping rồi bấm Ghi, hoặc bỏ file.';status.className='statusline bad'}else if(unmapped.length){status.textContent='Còn '+unmapped.length+' file chưa gán biểu cảm. Chọn biểu cảm ở từng dòng rồi bấm Ghi.';status.className='statusline bad'}else if(pending.length){status.textContent='Có mapping chưa được ghi. Bấm Ghi trên từng dòng trước khi cài theme.';status.className='statusline'}else if(status.textContent.startsWith('Nhiều file cùng gán một biểu cảm:')||status.textContent.startsWith('Còn ')||status.textContent.startsWith('Có mapping chưa được ghi.')){status.textContent='';status.className='statusline'}}})THEME" \
    R"THEME(const faceGifFileAliases={neutral:'neutral',idle:'neutral',default:'neutral',relaxed:'neutral',binhthuong:'neutral',happy:'happy',smile:'happy',delicious:'happy',sad:'sad',cry:'sad',crying:'sad',disappointed:'sad',buon:'sad',angry:'angry',anger:'angry',tucgian:'angry',surprised:'surprised',shock:'surprised',shocked:'surprised',astonished:'surprised',wow:'surprised',panic:'surprised',ngacnhien:'surprised',sleepy:'sleepy',sleep:'sleepy',tired:'sleepy',buonngu:'sleepy',confused:'confused',thinking:'confused',boiroi:'confused',listening:'listening',dangnghe:'listening',laugh:'laugh',laughing:'laugh',funny:'laugh',joy:'laugh',cuoi:'laugh',love:'love',loving:'love',kiss:'love',heart:'love',dangyeu:'love',dizzy:'dizzy',chongmat:'dizzy',distracted:'distracted',unfocused:'distracted',mattaptrung:'distracted',devil:'devil',mischievous:'devil',silly:'devil',tinhnghich:'devil',confident:'confident',cool:'confident',tutin:'confident',yawn:'yawn',action_yawn:'yawn',ngap:'yawn',playful:'playful',wink:'playful',winking:'playful',nhaymat:'playful',speaking:'speaking',talk:'speaking',talking:'speaking',dangnoi:'speaking'};function faceGifKeyFromFilename(name){const stem=name.replace(/\.[^.]*$/,'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[đĐ]/g,'d').toLowerCase().replace(/[^a-z0-9]+/g,'');return faceGifFileAliases[stem]||null}function collectFaceGifFiles(){const pending=faceGifBatchFiles.filter(item=>item.pendingExpression!==item.expression);if(pending.length)throw Error('Có mapping chưa được ghi: '+pending.map(item=>item.file.name).join(', ')+'. Bấm Ghi trên từng dòng.');const unmapped=faceGifBatchFiles.filter(item=>!item.expression);if(unmapped.length)throw Error('Chưa gán biểu cảm cho: '+unmapped.map(item=>item.file.name).join(', ')+'. Chọn biểu cảm rồi bấm Ghi.');const grouped=new Map();for(const item of faceGifBatchFiles)grouped.set(item.expression,(grouped.get(item.expression)||[]).concat(item));const duplicates=Array.from(grouped.entries()).filter(([,items])=>items.length>1);if(duplicates.length)throw Error('Nhiều file cùng gán một biểu cảm: '+duplicates.map(([key,items])=>faceGifExpressionLabel(key)+' ← '+items.map(item=>item.file.name).join(', ')).join('; ')+'. Đổi mapping rồi bấm Ghi, hoặc bỏ file.');const files=new Map(Array.from(grouped.entries()).map(([key,items])=>[key,items[0].file]));return faceGifExpressionDefs.filter(([key])=>files.has(key)).map(([key])=>({key,file:files.get(key)}))})THEME" \
    R"THEME(async function installFaceGifTheme(){if(faceGifBusy)return;faceGifBusy=true;const button=$('faceGifInstall'),progress=$('faceGifProgress'),status=$('faceGifCreatorStatus'),progressText=$('faceGifProgressText');button.disabled=true;progress.value=0;let currentUpload='';let createdDirectory='';let installed=false;try{const name=$('faceGifName').value.trim();if(!name||new TextEncoder().encode(name).length>64)throw Error('Nhập tên theme dài tối đa 64 byte UTF-8.');let id=faceGifSlug($('faceGifId').value||name);if(!id)throw Error('Mã theme cần có chữ cái hoặc chữ số.');$('faceGifId').value=id;const selected=collectFaceGifFiles();if(!selected.length)throw Error('Chọn ít nhất một file GIF.');if(selected.some(item=>item.file.size>10*1024*1024||item.file.size===0))throw Error('Mỗi GIF nguồn phải từ 1 byte đến 10 MiB.');if(faceThemeCatalog.filter(theme=>!theme.builtin).length>=16)throw Error('Đã có 16 theme tùy chỉnh. Xóa một theme trước khi cài thêm.');const storage=await faceStorageApi({op:'status'});if(storage.state!=='mounted')throw Error('Hãy kết nối thẻ microSD trước khi cài theme.');let rootListing;try{rootListing=await faceStorageApi({op:'list',path:'/robot/themes'})}catch(error){if(error.status!==404)throw error}if(rootListing&&(rootListing.entries||[]).some(entry=>entry.name===id||entry.name===id+'.json'))throw Error('Mã theme đã có dữ liệu trên thẻ. Hãy đổi mã khác để tránh ghi đè.');const background=$('faceGifBackground').value.toLowerCase();const folder='/robot/themes/'+id;try{await faceStorageApi({op:'list',path:folder});throw Error('Mã theme đã có thư mục trên thẻ. Hãy đổi mã khác để tránh ghi đè.')}catch(error){if(error.status!==404)throw error}await faceEnsureDirectory('/robot');await faceEnsureDirectory('/robot/themes');await faceEnsureDirectory(folder);createdDirectory=folder;const expressions=[];for(let index=0;index<selected.length;index++){const item=selected[index];if((await faceStorageApi({op:'music_player'})).active)throw Error('Đang phát nhạc từ thẻ. Dừng phát rồi cài theme để không tranh chấp microSD.');progressText.textContent='Đang chuẩn hóa '+item.file.name+' ('+(index+1)+'/'+selected.length+')…';const normalized=await faceGifWorker(item.file,background,value=>{progress.value=Math.round((index+value/100)*85/selected.length)});const path=folder+'/'+item.key+'.gif';currentUpload=path;progressText.textContent='Đang tải '+item.key+'.gif · '+normalized.width+'×'+normalized.height+' · '+normalized.frames+' khung';await faceThemeUpload(path,new Blob([normalized.buffer],{type:'application/octet-stream'}),(sent,total)=>{progress.value=Math.round(((index+sent/total)*85)/selected.length)});currentUpload='';expressions.push(item.key)}const manifest={version:2,id,name,style:$('faceGifStyle').value,primary:$('faceGifPrimary').value.toUpperCase(),accent:$('faceGifAccent').value.toUpperCase(),tear:$('faceGifTear').value.toUpperCase(),background:background.toUpperCase(),expressions};progressText.textContent='Đang kiểm tra và đăng ký theme…';await faceThemeAction('install','',JSON.stringify(manifest));installed=true;createdDirectory='';progress.value=100;progressText.textContent='Đã cài '+expressions.length+' biểu cảm vào '+folder;status.textContent='Theme đã sẵn sàng. Chọn theme trong danh sách phía trên để kích hoạt.';status.className='statusline good'}catch(error){if(currentUpload){try{await faceStorageApi({op:'abort_upload',path:currentUpload},{method:'POST'})}catch(_){}}if(createdDirectory&&!installed){try{const state=await json('/api/face_themes');if(!state.busy)await faceStorageApi({op:'delete',path:createdDirectory},{method:'POST'})}catch(_){}}status.textContent=error.message||'Không cài được theme.';status.className='statusline bad';progressText.textContent='Có thể cần dừng phát nhạc hoặc kiểm tra thẻ microSD rồi thử lại.'}finally{faceGifBusy=false;button.disabled=false;await loadFaceThemes().catch(()=>{})}})THEME"
